def spiral_order(matrix):
    """Return elements of a rectangular matrix in clockwise spiral order."""
    if not matrix or not matrix[0]:
        return []

    result = []
    top, bottom = 0, len(matrix) - 1
    left, right = 0, len(matrix[0]) - 1

    while top <= bottom and left <= right:
        # across the top row
        for col in range(left, right + 1):
            result.append(matrix[top][col])
        top += 1

        # down the right column
        for row in range(top, bottom + 1):
            result.append(matrix[row][right])
        right -= 1

        # back along the bottom row (if a row remains)
        if top <= bottom:
            for col in range(right, left - 1, -1):
                result.append(matrix[bottom][col])
            bottom -= 1

        # up the left column (if a column remains)
        if left <= right:
            for row in range(bottom, top - 1, -1):
                result.append(matrix[row][left])
            left += 1

    return result
```

The four boundaries shrink inward after each pass; the two extra `if` checks prevent re-visiting a row or column when only a single row or column is left.
